namespace BlazorApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();

    private readonly string[] _templates =
    [
        "New comment on your post",
        "Your build succeeded",
        "Deployment to production complete",
        "New pull request review requested",
        "CI pipeline failed for branch main",
        "Your subscription is expiring soon",
        "New team member joined the project",
        "Security alert: dependency update available",
        "Weekly report is ready",
        "Server health check warning"
    ];

    public Task<List<NotificationItem>> GetInitialNotificationsAsync()
    {
        lock (_lock)
        {
            var items = new List<NotificationItem>();
            for (int i = 0; i < 3; i++)
            {
                items.Add(new NotificationItem
                {
                    Id = _nextId++,
                    Message = _templates[Random.Shared.Next(_templates.Length)],
                    Timestamp = DateTime.UtcNow.AddMinutes(-Random.Shared.Next(1, 60))
                });
            }
            return Task.FromResult(items);
        }
    }

    public Task<List<NotificationItem>> CheckForNewNotificationsAsync()
    {
        lock (_lock)
        {
            // ~50% chance of a new notification each poll
            if (Random.Shared.Next(2) == 0)
                return Task.FromResult(new List<NotificationItem>());

            var item = new NotificationItem
            {
                Id = _nextId++,
                Message = _templates[Random.Shared.Next(_templates.Length)],
                Timestamp = DateTime.UtcNow
            };
            return Task.FromResult(new List<NotificationItem> { item });
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using BlazorApp.Services
@inject NotificationService NotificationSvc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading...</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<NotificationItem>? notifications { get; set; }

    private CancellationTokenSource? _cts;

    protected override async Task OnInitializedAsync()
    {
        // Only fetch if not already restored from prerender state
        notifications ??= await NotificationSvc.GetInitialNotificationsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
                var newItems = await NotificationSvc.CheckForNewNotificationsAsync();
                if (newItems.Count > 0)
                {
                    notifications?.AddRange(newItems);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

